def binary_search(values, target):
    def search(left, right):
        if left > right:
            return -1
        middle = left + (right - left) // 2
        if values[middle] == target:
            return middle
        if values[middle] < target:
            return search(middle + 1, right)
        return search(left, middle - 1)
    return search(0, len(values) - 1)

def max_subarray(values):
    if not values:
        raise ValueError("non-empty list required")
    ending = best = values[0]
    for i in range(1, len(values)):
        ending = max(values[i], ending + values[i])
        best = max(best, ending)
    return best

def pairs_sum(values, target):
    seen, pairs = set(), set()
    for value in values:
        other = target - value
        if other in seen:
            pairs.add((min(value, other), max(value, other)))
        seen.add(value)
    return sorted(pairs)
